head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > deleteAllTabs]<br/>컴포넌트에 정의된 모든 Tab 페이지를 제거합니다.",
    "validation" : [
        "컴포넌트에 정의된 모든 Tab 페이지를 제거합니다.",
        "전체 Tab 페이지가 제거되면 TabControl 컴포넌트엔 빈화면이 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createBasicTabControl();  
}



scwin.btn_getTabCount_onclick = function (e) {
    let rtn = target1.getTabCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getTabCount : " + rtn);

    let content1 = document.querySelector('div[id*=target1_contents_content1_body]');
    let content2 = document.querySelector('div[id*=target1_contents_content2_body]');
    let content3 = document.querySelector('div[id*=target1_contents_content3_body]');

    if (content1 == null && content2 == null && content3 == null)
        wf_body_bottom.getObj("scwin").setReturnValue("Content is empty");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("Content is not empty");
}



scwin.btn_deleteAllTabs_onclick = function (e) {
	target1.deleteAllTabs();

    scwin.btn_getTabCount_onclick();
};
